// Normalize incoming lead payload.
// RULE: pass every incoming field through. Fields added on the client (event_id,
// fbp, fbc, client_ip_address, client_user_agent, and anything added later)
// must survive this node or they reach nothing downstream.
// Do NOT reintroduce a field whitelist here.

const raw = $input.first().json;

function clean(val) {
  return (val ?? '').toString().trim();
}

// lead_id: L-{YYYYMMDD}-{6 lowercase alphanumeric}, Asia/Bangkok date.
// Reuse an incoming lead_id if one is present so retries don't mint a new key.
function makeLeadId() {
  const bkk = new Date(Date.now() + 7 * 60 * 60 * 1000);
  const ymd = bkk.toISOString().slice(0, 10).replace(/-/g, '');
  const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let suffix = '';
  for (let i = 0; i < 6; i++) {
    suffix += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return `L-${ymd}-${suffix}`;
}

// Spread first, then overwrite with cleaned/defaulted values.
const normalized = {
  ...raw,
  lead_id:      clean(raw.lead_id) || makeLeadId(),
  name:         clean(raw.name),
  email:        clean(raw.email).toLowerCase(),
  phone:        clean(raw.phone),
  restaurant:   clean(raw.restaurant),
  service:      clean(raw.service),
  message:      clean(raw.message),
  page_path:    clean(raw.page_path),
  page_url:     clean(raw.page_url),
  page_type:    clean(raw.page_type) || 'other',
  form_name:    clean(raw.form_name) || 'lead',
  submitted_at: clean(raw.submitted_at) || new Date().toISOString(),
  source:       clean(raw.source) || 'website',
  site:         clean(raw.site) || 'rampupth',
};

// Never forward the captcha token; it is already verified by /api/lead-relay.
delete normalized.turnstile_token;

return [{ json: normalized }];

// Validate: name is required, plus AT LEAST ONE contact channel.
// Some funnels (app/grab-offer) are phone/LINE only and send email: ''.
// Requiring name AND email AND phone silently 422'd every one of those leads.
// This mirrors the rule already enforced in app/api/lead-relay/route.ts.

const item = $input.first().json;

const hasName  = (item.name  ?? '').toString().trim() !== '';
const hasEmail = (item.email ?? '').toString().trim() !== '';
const hasPhone = (item.phone ?? '').toString().trim() !== '';

const valid = hasName && (hasEmail || hasPhone);

const missing = [];
if (!hasName) missing.push('name');
if (!hasEmail && !hasPhone) missing.push('email or phone');

return [{
  json: {
    ...item,
    _valid: valid,
    _missing: missing.join(', '),
  },
}];
